head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/protected_dep_cal.js");
scwin.vScrenID = "ULDSTF40208.xml";
scwin.gPrtdepoId; // PRTDEPO_ID
scwin.gIsurCd; // ISUR_CD
scwin.seq; //일련번호
scwin.gPrtdepoEndDd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//데이타 가져와서 뿌리기 List
scwin.fn_list_sync = function() {
    //alert("보호예수ID(PRTDEPO_ID) : gIsurCd-->"+gIsurCd);

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PROTECTED_DEPOSITION_ADMINISTRATIVE_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.prtdepomgt.prtdepo_rto_adm_dtl" + "&{P}param01=" + scwin.gIsurCd + //
        "&{P}param02=" + scwin.gPrtdepoEndDd; //

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};



//조치일련번호 Set
scwin.fn_setSeq = function(obj) {
    scwin.seq = dts_List.getCellData(eval(obj), "SEQ");
};

//조치일련번호 Get
scwin.fn_getSeq = function() {
    return scwin.seq;
};


//보호예수ID Set
scwin.fn_setId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(eval(obj), "PRTDEPO_ID");
};

//조치일련번호 Get
scwin.fn_getId = function() {
    return scwin.gIsurCd;
};
scwin.fn_setPrtdepoId = function(obj) {
    scwin.gPrtdepoId = dts_List.getCellData(eval(obj), "PRTDEPO_ID");
};
scwin.fn_getPrtdepoId = function() {
    return scwin.gPrtdepoId;
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //alert("rowCnt-->"+rowcount);

    //alert("dts_List.CountRow-->"+dts_List.CountRow);

};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_close_onclick = function() {
    self.close();
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    scwin.fn_setPrtdepoId(row);
    await $c.frame.CreateDialogFrame("ULDSTF40209", "/lstmgt/ULDSTF40209.gfm", "의무보유 수정", 200, 200, 830, 430, "window");
    scwin.fn_list_sync();
};
scwin.btn_input_onclick = async function() {
    scwin.gPrtdepoId = "input";
    await $c.frame.CreateDialogFrame("ULDSTF40209", "/lstmgt/ULDSTF40209.gfm", "의무보유 수정", 200, 200, 830, 430, "window");
    scwin.fn_list_sync();
};
scwin.gform_onload = function() {
    var fParent = $c.frame.path("../");
    scwin.gIsurCd = fParent.fn_getId();
    scwin.gPrtdepoEndDd = fParent.fn_getPrtdepoEndDd();

    //alert("gIsurCd=" + gIsurCd + " gPrtdepoEndDd=" + gPrtdepoEndDd);

    scwin.fn_list_sync();
};
